mapper.update:
UPDATE comment c
    INNER JOIN post p ON p.id = c.post_id
SET
    c.content = #{content},
    c.version = c.version + 1,
    c.updated_at = CURRENT_TIMESTAMP(6)
WHERE c.id = #{commentId}
    AND c.post_id = #{postId}
    AND p.board_id = #{boardId}
    AND c.author_id = #{authorId}
    AND c.version = #{version}
    AND c.deleted_at IS NULL
    AND p.deleted_at IS NULL
    AND p.blinded_at IS NULL
    AND c.blinded_at IS NULL

UPDATE comment c
    INNER JOIN post p ON p.id = c.post_id
SET
    c.deleted_at = CURRENT_TIMESTAMP(6),
    c.updated_at = CURRENT_TIMESTAMP(6),
    c.version = c.version + 1
WHERE c.id = #{commentId}
    AND c.post_id = #{postId}
    AND p.board_id = #{boardId}
    AND c.version = #{version}
    AND c.deleted_at IS NULL
    AND p.deleted_at IS NULL

UPDATE comment
SET blinded_at = CURRENT_TIMESTAMP(6),
    version = version + 1,
    updated_at = updated_at
WHERE id = #{commentId}
    AND post_id = #{postId}
    AND version = #{version}
    AND deleted_at IS NULL
    AND blinded_at IS NULL

UPDATE comment
SET blinded_at = NULL,
    blind_report_base_count = #{acceptedReportCount},
    version = version + 1,
    updated_at = updated_at
WHERE id = #{commentId}
    AND post_id = #{postId}
    AND version = #{version}
    AND deleted_at IS NULL
    AND blinded_at IS NOT NULL
